using System;using System.Linq;using System.Xml;using BeamScheduleFormatter;
class FinishTypeGroupingTests {
 static int checks;static void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}static void Main(){var a=new FinishItem{Id="W1",Code="WT1",Category="Wall",MaterialName=" Porcelain   Glazed Tiles and Trims ",Length=2,Width=3,Quantity=1};var b=new FinishItem{Id="F1",Code="FT9",Category="Floor",MaterialName="porcelain glazed tiles and trims",Length=5,Width=5,Quantity=1};var c=new FinishItem{Id="F2",Code="FT2",Category="Floor",MaterialName=FinishTypeCatalog.Names[5],Length=2,Width=2,Quantity=1};var items=new[]{a,b,c};Func<FinishItem,double> area=f=>f.Length*f.Width*f.Quantity;var totals=FinishTypeRegistry.Totals(items,area);Check(totals.Count==2,"Different codes prevented grouping or distinct finishes merged");Check(totals.First(t=>t.Key==FinishTypeRegistry.Key(a.MaterialName)).Area==31,"Case/space normalized cross-category sum");var registry=new FinishTypeRegistry();registry.Include(items.Select(f=>f.MaterialName));Check(registry.Rows.Count==2,"Duplicate material cell allocated");int glazed=registry.Rows[0].Row;registry.Include(new[]{FinishTypeCatalog.Names[8]});Check(registry.Rows[0].Row==glazed&&registry.Rows[2].Row>registry.Rows[1].Row,"New type shifted existing cells");var empty=registry.Table(FinishTypeRegistry.Totals(new[]{c},area));Check(Convert.ToDouble(empty.Rows[glazed-2,1])==0,"Removed material still shows old area");var doc=new XmlDocument();doc.LoadXml("<ProgramOfWorks/>");registry.Write(doc.DocumentElement);var loaded=FinishTypeRegistry.Read(doc.DocumentElement);Check(loaded.Rows.Select(r=>r.Key+":"+r.Row).SequenceEqual(registry.Rows.Select(r=>r.Key+":"+r.Row)),"Cell assignments changed after save/open");var catalog=FinishTypeCatalog.Table(totals);Check(catalog.StartRow==35&&catalog.StartColumn==4&&catalog.Rows.GetLength(0)==21,"Preset block location");Check(Convert.ToDouble(catalog.Rows[4,1])==31&&Convert.ToDouble(catalog.Rows[5,1])==4&&Convert.ToDouble(catalog.Rows[0,1])==0,"Preset totals/zero unused types");var waterproof=new FinishItem{Category="Floor",MaterialName=FinishTypeCatalog.Names[0],Length=3,Width=2,Quantity=1};var waterproofTable=FinishTypeCatalog.Table(FinishTypeRegistry.Totals(new[]{waterproof},area));Check(Convert.ToDouble(waterproofTable.Rows[0,1])==6,"3-coat item multiplied measured area");Check(FinishTypeCatalog.KindFor(FinishTypeCatalog.Names[0])=="Other"&&FinishTypeCatalog.KindFor(FinishTypeCatalog.Names[4])=="Tiles","Waterproofing misclassified as a tile deduction");Check(FinishTypeCatalog.IsPlaster(FinishTypeCatalog.Names[15]),"Paper plaster classification");doc.DocumentElement["FinishTypeCells"].AppendChild(doc.DocumentElement["FinishTypeCells"].FirstChild.CloneNode(true));bool bad=false;try{FinishTypeRegistry.Read(doc.DocumentElement);}catch{bad=true;}Check(bad,"Duplicate saved cell accepted");Console.WriteLine("PASS: "+checks+" finish-type grouping, case/space normalization, stable cells, preset totals, waterproofing coat basis and save/open checks.");}
}
